"""Export native outputs and write an executor explanation; no physical model calculation."""
import csv,json,math,os
from pathlib import Path
H=Path(__file__).resolve().parents[1];R=H/'results';P='stellarator_09__stellaris__'
read=lambda p:json.loads(p.read_text())
write=lambda p,v:p.write_text(json.dumps(v,indent=2,allow_nan=False)+'\n')
key=lambda p:json.dumps({k:float(v) for k,v in p.items()},sort_keys=True)
props={key(x['point']):x for x in read(H/'preparation/proposals.json')}
catalog=read(R/'predicate-catalog.json');defaults=read(H/'preparation/resolved-defaults.json')
rows=[]
for case in read(R/'native-cases.json'):
 meta=props[key(case['inputs'])];values=case['outputs'];defined=bool(values[P+'fuel_cycle__inventory__defined_flag'])
 row={'arm_id':'arm-native','proposal_id':meta['id'],'case_id':case['candidate_id'],'family':meta['family'],'inventory_defined':defined,'wholeplant_satisfied':all(v=='satisfied' for v in case['verdicts'].values())}
 nonbreeding={n+'_'+unit for n in ('feed','plasma','processor','buffer','reserve','prefill') for unit in ('atoms','kg')}
 nonbreeding|={n+'_'+unit for n in ('burn','injection','exhaust','recycle','recycle_loss') for unit in ('kg_s','kg_day')}
 nonbreeding|={'annual_'+n+'_kg' for n in ('burn','injection','exhaust','recycle','recycle_loss')}
 nonbreeding|={'dt_'+n+'_'+unit for n in ('injection','processor') for unit in ('kg_s','kg_day')}
 nonbreeding|={'calendar_processor_kg_s','recycle_delay_s','breeding_delay_s','startup_horizon_s','max_decay_residence','defined_flag'}
 for full,value in values.items():
  if full.startswith(P+'fuel_cycle__inventory__'):
   short=full.removeprefix(P+'fuel_cycle__inventory__');row[short]=value if defined or short in nonbreeding else None
 for name,channel in {'fusion_power_MW':'plasma__fusion__p_fus','net_power_MW':'pb__p_net','availability':'calendar__availability','LCOE_dollars_MWh':'lcoe_calc__lcoe','total_capital_dollars':'total_capital__total_capital','tbr_required':'fuel_cycle__fuel__tbr_required','tbr_mean':'blanket__breeding__tbr_mean','tbr_lower':'blanket__breeding__tbr_lower','breeding_margin':'breeding_adequacy__numerical_margin'}.items():row[name]=values[P+channel]
 row['violated']=';'.join(catalog[c]['source_local_identity'] for c,v in case['verdicts'].items() if v!='satisfied')
 row.update(case['verdicts']);rows.append(row)
write(R/'interpreted-cases.json',rows)
with (R/'points.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
with (R/'all-native-channels.csv').open('w',newline='') as f:
 fields=['proposal_id','case_id']+read(H/'preparation/required-channels.json');w=csv.DictWriter(f,fieldnames=fields);w.writeheader()
 for c in read(R/'native-cases.json'):w.writerow({'proposal_id':props[key(c['inputs'])]['id'],'case_id':c['candidate_id']}|{k:c['outputs'][k] for k in fields[2:]})
by={x['proposal_id']:x for x in rows};b=by['reference'];n=len(rows)
summary={'cases':n,'all_defined':all(x['inventory_defined'] for x in rows),'wholeplant_satisfied':sum(x['wholeplant_satisfied'] for x in rows),'reference':b,'ranges':{k:{'min':min(x[k] for x in rows),'max':max(x[k] for x in rows)} for k in ('total_kg','working_kg','reserve_kg','startup_minimum_kg','startup_conservative_kg','exhaust_kg_day','dt_processor_kg_day','annual_external_shortfall_kg','LCOE_dollars_MWh')},'predicate_counts':{cid:{s:sum(r[cid]==s for r in rows) for s in ('satisfied','violated','indeterminate')} for cid in catalog}}
write(R/'summary.json',summary)
lines=['# Tritium held, startup supply and processing demand','',f'The reference model holds **{b["total_kg"]:.3f} kg of tritium**, including **{b["reserve_kg"]:.3f} kg of interruption reserve**. Its conservative initial external supply is **{b["startup_conservative_kg"]:.3f} kg** for the declared {b["startup_horizon_s"]/86400:g}-day startup horizon. Running exhaust processing receives **{b["exhaust_kg_day"]:.3f} kg T/day**, or **{b["dt_processor_kg_day"]:.3f} kg D+T/day**. These are represented-boundary calculations under explicit assumptions, not evidence that tritium can be procured or that a plant can sustain itself. All values below come from [native points](results/points.csv); [all native channels](results/all-native-channels.csv) retain the complete executable output.','', '## What is being counted','', 'Inventory is tritium present in equipment or storage. Throughput is material passing through per unit time. The source burn fraction sets how much tritium circulates for each atom burned; the recovery fraction applies to unburned exhaust. The processor inventory is counted before recovery loss. Breeding-zone and extraction inventories use gross production; extraction efficiency acts once at the final outlet.','', '| Represented stock | Reference kg T | Basis |','|---|---:|---|']
for field,title,basis in [('feed','Injection equipment','Injection flow × feed residence'),('plasma','Plasma','Integrated tritium particle density'),('processor','Combined exhaust processor','Unburned exhaust × processing residence'),('blanket','Breeding zone','Gross bred flow × blanket release time'),('extraction','Extraction equipment','Gross bred flow × extraction residence'),('buffer','Usable working buffer','Injection flow × buffer duration'),('reserve','Interruption reserve','Injection flow × disrupted fraction × reserve duration')]:lines.append(f'| {title} | {b[field+"_kg"]:.6g} | {basis} |')
lines+=['',f'The first six entries total {b["working_kg"]:.6g} kg working inventory. The separately declared reserve produces the {b["total_kg"]:.6g} kg represented total. Unmodeled wall retention, coolant permeation, detritiation, impurity/carrier streams and bypass mean this is not a qualified total-plant inventory.','', '## What startup means','', 'Feed equipment, plasma and working buffer are prefilled; reserve is kept separately. The exhaust processor and breeding/extraction stages start empty. Full-power operation begins immediately. Recycled fuel arrives after the combined processing delay, and bred fuel after the sum of breeding-zone and extraction delays. This is a deterministic-delay approximation, not an ignition or ramp simulation.','',f'Reference prefill is {b["prefill_kg"]:.6g} kg, the maximum subsequent storage draw is {b["startup_deficit_kg"]:.6g} kg, and reserve is {b["reserve_kg"]:.6g} kg. Together they give {b["startup_minimum_kg"]:.6g} kg no-decay minimum initial supply. A conservative {b["startup_decay_allowance_kg"]:.6g} kg decay allowance raises this to {b["startup_conservative_kg"]:.6g} kg. Working inventory is not added again: processor fill is already in the storage draw, and blanket inventory is produced internally.','', 'The decay allowance assumes replacement fuel can reach the affected stock within the abstract supply boundary. It is not a demonstrated transport or availability guarantee. A finite commissioning supply does not remedy a continuing operating deficit.','', '## Source scenarios and operating choices','', '| Input family | Candidate values | Authority and limitation |','|---|---|---|','| Feed residence | 20/30 min | Abdou Table2 technology scenarios |','| Combined cleanup/separation | 1.3/4/5 h | Abdou Table2; no invented split between stages |','| Breeding-zone release | 0.1/1 day | Abdou Table3 scenarios; no helium/PbLi qualification |','| Extraction delay | 0/1/5 days | Table3; zero is an ideal online diagnostic |','| Reserve and buffer | 0/6/24 h reserve; disrupted fraction0.25/1; buffer0/1 h | Explicit policies, not established reliability requirements |','| Burn/recovery/extraction | burn0.025/0.05/0.10; recovery0.99/0.999/1; extraction0.95/1 | Conditional performance sensitivities; inherited reference factors unchanged |','| Other diagnostics | density±10%; zero decay;4500-day passive shutdown; live unplanned fraction0.1/0.5/0.9 | Causal model inputs and explicit mathematical/operating scenarios |','', 'Source facts and source-transfer limits are retained in [research](preparation/references/research.md), [released design](preparation/references/design.md) and the original-source witness copies. Fast and slow combinations are engineered scenarios. They are not confidence intervals, physical bounds or optimization results.','', '## Response across the finite list','', '| Case | Held kg T | Startup kg T, conservative | Processor kg T/day | Annual shortfall kg T | LCOE $/MWh |','|---|---:|---:|---:|---:|---:|']
for r in rows:lines.append(f'| {r["proposal_id"]} | {r["total_kg"]:.4f} | {r["startup_conservative_kg"]:.4f} | {r["exhaust_kg_day"]:.4f} | {r["annual_external_shortfall_kg"]:.5g} | {r["LCOE_dollars_MWh"]:.3f} |')
eta=by['extraction-efficiency-0.95'];ext=by['deficient-10d-extension'];fast=by['combined-fast'];slow=by['combined-slow']
lines+=['',f'The combined fast and slow cases hold {fast["total_kg"]:.3f} and {slow["total_kg"]:.3f} kg T and require {fast["startup_conservative_kg"]:.3f} and {slow["startup_conservative_kg"]:.3f} kg conservative startup supply. Their throughput is unchanged from reference because residence and reserve policies do not change burn or circulating flow. The full selected list spans {summary["ranges"]["total_kg"]["min"]:.3f}–{summary["ranges"]["total_kg"]["max"]:.3f} kg held and {summary["ranges"]["startup_conservative_kg"]["min"]:.3f}–{summary["ranges"]["startup_conservative_kg"]["max"]:.3f} kg conservative startup supply.','',f'The extraction-efficiency0.95 case has signed running makeup {eta["makeup_signed_kg_s"]:.6g} kg/s. Extending the startup horizon by ten days increases conservative initial supply from {eta["startup_conservative_kg"]:.3f} to {ext["startup_conservative_kg"]:.3f} kg while its operating inventory and processor capacity remain unchanged. This separates a longer initial supply horizon from the continuing deficit.','', 'Lower burn fraction increases injection, exhaust processing and reserve needs at fixed fusion power. Faster recycling lowers processor stock and startup draw. Recovery changes permanent losses and return supply; its assumed technology has no new equipment price in this model. Calendar availability changes annual operating flows while installed running capacity remains set by the full-power point. Maintained-stock decay continues through calendar downtime; passive shutdown decay is a separate diagnostic.','', '![Inventory and startup response](results/inventory-response.png)','', '## Verification and limits','',f'All {n} native cases are retained. {summary["wholeplant_satisfied"]} satisfy every whole-plant screen; this study claims no feasible plant or boundary. The reference fails: {b["violated"]}. [Constraint details](results/native-cases.json) retain every qualified predicate identity and outcome. LCOE is reported for context; new inventory and throughput outputs do not price a fuel-processing plant.','', 'The independent oracle checks every mapped scalar and independently derives every authored predicate at every point. Separate upstream tests verify hand cases, integrated startup trajectories, plasma-profile integration and decay bounds. Shared source assumptions and neutron-transport data are not independent physical validation. Twenty-two exported numeric channels are outside the oracle map and remain native evidence only. Final independent study and rubric review are coordinator-owned and pending at this executor snapshot.','', 'The calculations provide a useful conditional estimate and expose its main drivers. They do not establish reactor-specific residence performance, trapping/release behavior, purchased tritium availability, equipment reliability, full fuel-cycle self-sufficiency or complete process costs. A future process design must connect residence, recovery, buffer and reserve choices to actual equipment and operating constraints.']
lines+=['','The906 mapped scalar channels comprise892 numeric channels and14 Boolean cooling flags. The22 unmapped numeric channels are listed explicitly in [coverage exceptions](results/unmapped-native-channels.json); every new inventory output is mapped.']
(H/'report.md').write_text('\n'.join(lines)+'\n')
