y=list(range(n));labels=[r['proposal_id'] for r in rows]
axes[0].barh([i-.18 for i in y],[r['total_kg'] for r in rows],height=.34,label='Held tritium')
axes[0].barh([i+.18 for i in y],[r['startup_conservative_kg'] for r in rows],height=.34,label='Conservative startup supply')
axes[0].set_yticks(y,labels);axes[0].invert_yaxis();axes[0].set_xlabel('kg tritium');axes[0].legend(loc='upper right')
axes[1].barh(y,[r['exhaust_kg_day'] for r in rows],height=.6,color='#46788e');axes[1].set_xlabel('Running processor inlet, kg T/day')
for ax in axes:ax.grid(axis='x',alpha=.25);ax.set_axisbelow(True)
fig.suptitle('Fuel inventory and startup: conditional source and policy scenarios')
fig.tight_layout();fig.savefig(R/'inventory-response.png',dpi=180);fig.savefig(R/'inventory-response.svg');plt.close(fig)
